properties.query:
let vpn_events = SigninLogs | where AppDisplayName has_any ("VPN", "GlobalProtect", "AnyConnect") and ResultType == 0 | summarize vpn_time=min(TimeGenerated) by UserPrincipalName, IpAddress;
let recon_events = SecurityEvent | where EventID in (4662, 5136) | summarize recon_time=min(TimeGenerated) by SubjectUserName;
let lateral_events = SecurityEvent | where EventID == 4624 and LogonType == 3 | summarize lat_time=min(TimeGenerated) by TargetUserName;
vpn_events | join kind=inner recon_events on $left.UserPrincipalName == $right.SubjectUserName | where recon_time - vpn_time between (0min .. 60min)
